@push('scripts')<script>document.addEventListener('DOMContentLoaded',()=>{const slides=[...document.querySelectorAll('.dj-slide')],dots=[...document.querySelectorAll('.dj-slider-dots i')];if(!slides.length)return;let i=0,t;const show=n=>{i=(n+slides.length)%slides.length;slides.forEach((s,k)=>s.classList.toggle('active',k===i));dots.forEach((d,k)=>d.classList.toggle('active',k===i))};const next=()=>show(i+1);document.querySelector('[data-dj-slide="next"]')?.addEventListener('click',next);document.querySelector('[data-dj-slide="prev"]')?.addEventListener('click',()=>show(i-1));t=setInterval(next,5500);document.querySelector('.dj-slider')?.addEventListener('mouseenter',()=>clearInterval(t));document.querySelector('.dj-slider')?.addEventListener('mouseleave',()=>t=setInterval(next,5500));});</script>@endpush